 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    pivots = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    if len(pivots) < 2:
        return [row[:] for row in grid]

    # The pivot surrounded by the motif is its source; the isolated 5 is
    # the target at which that same relative pattern is reproduced.
    scores = []
    for r, c in pivots:
        nearby = sum(
            1 for rr in range(max(0, r - 3), min(h, r + 4))
            for cc in range(max(0, c - 3), min(w, c + 4))
            if (rr, cc) != (r, c) and grid[rr][cc] != 0
        )
        scores.append(nearby)
    source_index = max(range(len(pivots)), key=lambda i: scores[i])
    sr, sc = pivots[source_index]
    tr, tc = next(p for i, p in enumerate(pivots) if i != source_index)

    offsets = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r, c) != (sr, sc) and abs(r - sr) <= 3 and abs(c - sc) <= 3:
                offsets.append((r - sr, c - sc, grid[r][c]))

    out = [row[:] for row in grid]
    out[tr][tc] = 0
    for dr, dc, color in offsets:
        rr, cc = tr + dr, tc + dc
        if 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = color
    return out
